const {chromium} = require(process.env.FLEET_PLAYWRIGHT_MODULE);
const assert = require('node:assert/strict');
const origin = process.argv[2];
(async () => {
  const browser = await chromium.launch({channel: process.env.FLEET_BROWSER_CHANNEL || 'chrome', headless: true});
  try {
    const page = await browser.newPage({viewport: {width: 1360, height: 1100}});
    page.setDefaultTimeout(15000);
    const errors = [];
    page.on('pageerror', error => errors.push(error.message));
    const catalogUrl = origin + '/api/platform/v1/plugins';
    await page.route(catalogUrl, async route => {
      const response = await route.fetch();
      const body = await response.json();
      await route.fulfill({response, json: {...body, enrollment_ready: false, setup_error: 'command_signature_required'}});
    });
    await page.goto(origin + '/plugins', {waitUntil: 'domcontentloaded'});
    await page.getByText('接入新节点', {exact: true}).click();
    await page.getByText('平台命令签名尚未配置。请在 Hub 运行 python -m hub.plugins_setup，随后重启 Hub。', {exact: true}).waitFor();
    assert.equal(await page.getByRole('button', {name: '生成接入文件', exact: true}).isEnabled(), false);
    await page.unroute(catalogUrl);
    await page.goto(origin + '/plugins', {waitUntil: 'domcontentloaded'});
    await page.getByText('接入新节点', {exact: true}).click();
    await page.getByRole('textbox', {name: '新节点 ID', exact: true}).fill('browser-enrollment');
    await page.getByRole('textbox', {name: '节点名称', exact: true}).fill('Browser Enrollment');
    await page.getByRole('button', {name: '生成接入文件', exact: true}).click();
    const enrollment = await page.getByRole('link', {name: '下载节点接入文件'});
    await enrollment.waitFor();
    const content = await page.evaluate(async href => JSON.parse(await (await fetch(href)).text()), await enrollment.getAttribute('href'));
    assert.equal(content.node_id, 'browser-enrollment');
    assert.equal(content.hub_url, origin);
    assert.ok(content.credential.startsWith('browser-enrollment:'));
    await page.getByText('接入新节点', {exact: true}).click();
    await page.getByRole('button', {name: '启用插件', exact: true}).click();
    await page.getByRole('combobox', {name: '目标节点'}).selectOption('vm');
    await page.getByRole('button', {name: '启用此节点', exact: true}).click();
    await page.getByRole('button', {name: '检查状态', exact: true}).click();
    await page.getByText('认证正常', {exact: true}).waitFor();
    assert.equal(await page.locator('.plugin-account').count(), 2);
    await page.getByRole('button', {name: '登录 GitHub', exact: true}).click();
    await page.locator('.plugin-device-code').waitFor();
    assert.equal(await page.locator('.plugin-device-code').textContent(), 'ABCD-1234');
    await page.reload({waitUntil: 'domcontentloaded'});
    await page.locator('.plugin-device-code').waitFor();
    assert.equal(await page.getByRole('link', {name: '打开 GitHub 授权页面'}).getAttribute('href'), 'https://github.com/login/device');
    await page.getByRole('button', {name: '停用插件', exact: true}).click();
    await page.getByRole('button', {name: '取消登录', exact: true}).click();
    await page.waitForFunction(() => document.querySelector('.plugin-login-state')?.textContent === '已取消');
    await page.getByRole('button', {name: '启用插件', exact: true}).click();
    await page.getByRole('button', {name: '登录 GitHub', exact: true}).click();
    await page.locator('.plugin-device-code').waitFor();
    assert.equal((await page.request.post(origin + '/_fixture/authorize')).status(), 200);
    await page.waitForFunction(() => document.querySelector('.plugin-login-state')?.textContent === '已完成');
    await page.waitForFunction(() => [...document.querySelectorAll('.plugin-account')].some(n => n.textContent.includes('new-user') && n.textContent.includes('当前账号')));
    await page.getByRole('button', {name: '切换到 bob', exact: true}).click();
    await page.waitForFunction(() => [...document.querySelectorAll('.plugin-account')].some(n => n.textContent.includes('bob') && n.textContent.includes('当前账号')));
    await page.getByRole('textbox', {name: '仓库', exact: true}).fill('owner/repo');
    await page.getByRole('button', {name: '验证仓库访问'}).click();
    await page.waitForFunction(() => document.querySelector('.plugin-repo-result')?.textContent.includes('可推送'));
    page.once('dialog', dialog => dialog.accept());
    await page.getByRole('button', {name: '退出 bob', exact: true}).click();
    await page.waitForFunction(() => ![...document.querySelectorAll('.plugin-account')].some(n => n.textContent.includes('bob')));
    await page.getByRole('textbox', {name: 'GitHub 主机', exact: true}).fill('https://github.com');
    await page.getByRole('button', {name: '检查状态', exact: true}).click();
    await page.getByText('插件请求不合法或目标不存在', {exact: true}).waitFor();
    await page.getByRole('textbox', {name: 'GitHub 主机', exact: true}).fill('github.com');
    await page.getByRole('textbox', {name: 'GitHub 主机', exact: true}).blur();
    await page.getByText('认证正常', {exact: true}).waitFor();
    await page.screenshot({path: process.env.FLEET_PLUGIN_SCREENSHOT, fullPage: true});
    await page.setViewportSize({width: 390, height: 844});
    assert.equal(await page.evaluate(() => document.documentElement.scrollWidth > window.innerWidth), false);
    assert.deepEqual(errors, []);
  } finally { await browser.close(); }
})().catch(error => { console.error(error); process.exitCode = 1; });
